const exams=window.EXAMS,app=document.getElementById('app');
const originalQuestions=exams.map(e=>e.questions.slice());
let paused=false,pausedRemainingMs=0;
let questionOrder=[],choiceOrder={},examMode='demo',candidateName='',registrationName='';
const shareCache=new WeakMap();
const tr=(ko,en)=>window.APP_LANG==='en'?en:ko;
function certificationName(e){return 'AIPath Certified '+e.name+' — '+e.level;}
function modeLabel(mode=examMode){return mode==='full'?tr('정규 시험','Full exam'):tr('데모 시험','Demo exam');}
function durationMinutes(i=selected,mode=examMode){return mode==='full'?exams[i].minutes:Math.ceil(exams[i].minutes*10/exams[i].count);}
let renderEpoch=0;
let view='home',languageSwitchPending=false;
let selected=0,current=0,answers=[],flags=new Set(),deadline=0,timer=null,lastResult=null,active=false,filter='all',reviewFilter='all';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function inline(s){return esc(s.replace(/&#91;/g,'[').replace(/\\([\[\]~_*])/g,'$1')).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function md(s){const lines=(s||'').split('\n');let out='',i=0;while(i<lines.length){let l=lines[i];if(/^```/.test(l)){const code=[];i++;while(i<lines.length&&!/^```/.test(lines[i]))code.push(lines[i++]);i++;out+='<pre class="question-code" tabindex="0"><code>'+esc(code.join('\n'))+'</code></pre>';continue;}if(!l.trim()||/^---\s*$/.test(l)){i++;continue;}if(l.startsWith('|')){const rows=[];while(i<lines.length&&lines[i].startsWith('|')){const cells=lines[i++].split('|').slice(1,-1).map(x=>x.trim());if(cells.every(x=>/^:?-+:?$/.test(x)))continue;rows.push(cells);}out+='<div class="table-scroll"><table>'+rows.map((r,j)=>'<tr>'+r.map(c=>`<${j?'td':'th'}>${inline(c)}</${j?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';continue;}if(/^>/.test(l)){let block=[];while(i<lines.length&&/^>/.test(lines[i]))block.push(lines[i++].replace(/^>\s?/,''));out+='<blockquote>'+md(block.join('\n'))+'</blockquote>';continue;}if(/^#{1,6} /.test(l)){out+='<h3>'+inline(l.replace(/^#+ /,''))+'</h3>';i++;continue;}if(/^- /.test(l)){out+='<ul>';while(i<lines.length&&/^- /.test(lines[i]))out+='<li>'+inline(lines[i++].slice(2))+'</li>';out+='</ul>';continue;}out+='<p>'+inline(l)+'</p>';i++;}return out;}
function matchingLabel(q,id){const labels=q.options.map(o=>o.id).sort((a,b)=>String(a).localeCompare(String(b),'ko',{numeric:true})),index=choicesFor(q).findIndex(o=>o.id===id);return itemLabel(index<0?id:labels[index]);}
function questionPrompt(q){if(q.type!=='매칭')return md(q.type==='순서 배열'?attemptText(q,q.prompt,false):q.prompt);const body=md(matchingPromptText(q.prompt).split('\n').filter(line=>!line.trim().startsWith('|')).join('\n'));const table=(caption,rows,label)=>'<div class="table-scroll matching-table"><table><caption>'+caption+'</caption><thead><tr><th scope="col">'+tr('기호','Label')+'</th><th scope="col">'+tr('내용','Description')+'</th></tr></thead><tbody>'+rows.map(row=>'<tr><th scope="row">'+esc(label(row.id))+'</th><td>'+inline(row.text)+'</td></tr>').join('')+'</tbody></table></div>';return body+'<div class="matching-reference">'+table(tr('연결할 상황','Situations to match'),q.items,itemLabel)+table(tr('보기','Available options'),choicesFor(q),id=>matchingLabel(q,id))+'</div><details class="matching-overview"><summary>'+tr('보기 전체 확인','View all options')+' · '+q.options.length+'</summary>'+matchingOptionsList(q)+'</details>';}

function stop(){clearInterval(timer);timer=null;}
function go(html,nav='home',scroll=true){renderEpoch++;app.innerHTML=html;document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));document.getElementById('nav-'+nav)?.classList.add('active');if(scroll)window.scrollTo(0,0);}
function leave(next){if(active){showSiteModal({title:tr('시험을 나가시겠어요?','Leave this exam?'),message:tr('현재 답안과 진행 기록은 저장되지 않습니다. 시험을 계속하려면 돌아가기를 선택하세요.','Your answers and progress will not be saved. Choose Go back to continue your exam.'),confirmLabel:tr('시험 나가기','Leave exam'),cancelLabel:tr('돌아가기','Go back'),onConfirm:()=>{if(!active)return;stop();active=false;next?.();}});return false;}stop();return true;}
function home(nextFilter='all'){if(!leave(()=>home(nextFilter)))return;view='home';filter=nextFilter;const heroExam=exams[Math.floor(Math.random()*exams.length)];go(`<section class="hero"><div class="wrap hero-inner"><div><div class="eyebrow">YOUR NEXT CHAPTER, WITH AI</div><h1>AI를 이해하고,<br>실력으로 증명하세요.</h1><p>생성형 AI의 기초부터 개발, 아키텍처, 보안까지.<br>${tr(exams.length+'개 자격 과정에서 나의 다음 목표를 찾아보세요.','Find your next goal across '+exams.length+' certification paths.')}</p><div class="hero-links"><button class="btn" onclick="document.getElementById('catalog').scrollIntoView({behavior:'smooth'})">나에게 맞는 자격증 찾기 ↗</button><a class="btn secondary" href="/about?lang=${window.APP_LANG==='en'?'en':'ko'}">${tr('AIPath란?','About AIPath')} ↗</a></div></div><div class="hero-art"><div class="orbit"></div><div class="orbit two"></div><img class="cert-badge" src="badges/${heroExam.code}-symbol.svg" alt="${esc(heroExam.name)} ${esc(heroExam.level)} 인증 배지"><div class="float f1"><b>✦</b> Learn across platforms</div><div class="float f2"><b>✓</b> Learn. Practice. Achieve.</div></div></div></section><div class="introbar"><div class="wrap"><span><b>${exams.length}</b> 직무별 자격 과정</span><span><b>4</b> 역량별 레벨</span><span><b>${exams.reduce((n,e,i)=>n+(e.bankCount||originalQuestions[i].length),0)}</b> 해설을 포함한 연습 문항</span></div></div><section class="wrap section" id="catalog"><div class="section-head"><div><div class="eyebrow" style="color:#777a70;margin-bottom:10px">EXPLORE CERTIFICATIONS</div><h2>다음 목표를 선택하세요</h2><p class="sub">OpenAI · Anthropic · Google을 아우르는 생성형 AI 역량.</p></div><div class="tabs">${['all','Fundamental','Associate','Professional','Specialty'].map(f=>`<button class="tab ${filter===f?'selected':''}" onclick="home('${f}');document.getElementById('catalog').scrollIntoView()">${f==='all'?'전체':f}</button>`).join('')}</div></div><div class="cards">${catalogEntries().map(({e,i})=>filter!=='all'&&e.level!==filter?'':`<article class="card ${i===0?'featured':''}"><div class="card-top"><img class="course-badge" src="badges/${e.code}-symbol.svg" alt="${esc(e.name)} ${e.level} 인증 배지"><span class="level">${e.level.toUpperCase()}</span></div><span class="code">${e.code}</span><h3>${esc(e.name)}</h3><p>${esc(e.purpose.replace(/^이 시험에서는 응시자가 /,'').replace(/ 확인합니다\.$/,' 확인합니다.'))}</p><div class="meta"><span>정규 ${e.count}문항 · ${e.minutes}분</span><span>합격 ${e.threshold}%</span></div><div class="course-actions"><button class="course-info" onclick="detail(${i})">과정 소개</button><button class="course-enroll" onclick="start(${i})" aria-label="${e.code} 데모 시험 응시하기">데모 시험 →</button></div><span class="practice-count">문제은행 ${(e.bankCount||originalQuestions[i].length)}문항 · 데모 10문항</span></article>`).join('')}</div></section><section class="wrap" style="padding-bottom:46px"><div class="journey"><strong>기초부터 전문성까지.<br>나만의 학습 경로.</strong><div class="step"><b>01</b> 알아보기<br><span>응시 대상과 출제 영역 확인</span></div><div class="step"><b>02</b> 직접 풀기<br><span>직무별 시나리오에 도전</span></div><div class="step"><b>03</b> 돌아보기<br><span>해설과 근거 문서로 복습</span></div><button class="btn secondary" onclick="detail(0)">ALF부터 시작 →</button></div></section>`);}
function detail(i){if(!leave(()=>detail(i)))return;if(!originalQuestions[i].length){return loadCourseView(i,()=>detail(i));}view='detail';selected=i;const e=exams[i];const practiceMinutes=durationMinutes(i,'demo');go(`<div class="wrap"><div class="crumb"><button class="smallbtn" onclick="home()">자격증 둘러보기</button> / ${e.code}</div><section class="detail"><img class="detail-badge" src="badges/${e.code}-symbol.svg" alt="${esc(e.name)} 인증 배지"><div class="eyebrow" style="color:#a15a42">${e.level.toUpperCase()} · ${e.code}</div><h1>${esc(e.name)}</h1><p class="sub">${esc(e.purpose)}</p><div class="detail-enroll"><button class="btn dark" onclick="start(${i})">${e.code} 데모 시험 응시하기 →</button><span class="sub">10문항 · ${practiceMinutes}분 · 합격 ${e.threshold}%</span></div><div class="panel"><h2>시험 안내</h2><div class="detail-grid"><div>정규 시험 구성<b>${e.count}문항</b></div><div>정규 시험 시간<b>${e.minutes}분</b></div><div>합격 기준<b>${e.threshold}%</b></div></div><p class="sub"><b>권장 경험</b> · ${esc(e.experience)}</p><div class="practice-callout"><strong>10문항으로 체험하기</strong><p class="sub">10문항 · ${practiceMinutes}분 · 합격 기준 ${e.threshold}%<br>전체 문제은행에서 10문항을 무작위로 뽑습니다. 데모 시간은 정규 시험의 문항당 시간을 기준으로 계산합니다.</p><p class="note">${e.scoring==='equal'?tr('문항당 동일 배점이며, 복합 문항은 모든 답이 일치해야 득점합니다. 오답 감점은 없습니다.','Each question carries equal weight. All parts must be correct; there is no penalty for incorrect answers.'):tr('난이도 L1 · L2 · L3 · L4는 각각 1 · 2 · 3 · 4점이며, 총 배점 대비 100점으로 환산합니다. 복합 문항은 모든 답이 일치해야 점수를 받습니다.','Difficulty levels L1–L4 carry 1–4 points, normalized to a score out of 100. Multi-part questions earn points only when every answer is correct.')}</p><button class="btn" onclick="start(${i})">${e.code} 데모 시험 시작 →</button></div></div><div class="panel"><h2>출제 영역</h2>${e.domains.map(d=>`<div class="domain"><div><span>${d.id}. ${esc(d.name)}</span><b>${d.weight}%</b></div><div class="progress"><i style="width:${d.weight}%"></i></div></div>`).join('')}<p class="note">${e.code==='ASF'?tr('정규 시험 42 · 12 · 6문항, 데모 7 · 2 · 1문항을 영역별로 무작위 추출합니다.','Questions are sampled by domain: 42/12/6 for the full exam and 7/2/1 for the demo.'):tr('위 비율은 가이드의 정규 시험 기준입니다. 무작위로 뽑은 문항의 영역별 구성은 다를 수 있습니다.','These weights follow the full-exam guide. The domain mix of randomly sampled questions may vary.')}</p></div><div class="panel markdown"><h2>상세 시험 가이드</h2><p class="note">제공 가이드 기준일: ${e.guideDate||'2026-10-16'}</p>${md(e.guide)}</div></section></div>`);}
function openPractice(){if(active){exam();return;}detail(selected);}
function start(i=selected,mode='demo',registered=false){if(mode==='full'&&!registered){enroll(i);return;}if(mode==='full'&&(!cleanCandidate(registrationName)||cleanCandidate(registrationName).length>40)){enroll(i);return;}if(active&&!leave(()=>start(i,mode,registered)))return;if(!originalQuestions[i].length){return loadCourseView(i,()=>start(i,mode,registered));}candidateName=mode==='full'?cleanCandidate(registrationName):'';selected=i;examMode=mode==='full'?'full':'demo';current=0;randomizeAttempt(i);answers=exams[i].questions.map(()=>[]);flags=new Set();lastResult=null;reviewFilter='all';paused=false;pausedRemainingMs=0;active=true;deadline=Date.now()+durationMinutes(i)*60000;exam();startTimer();}
const secondsLeft=()=>window.REVIEW_PREVIEW?900:Math.max(0,Math.ceil((paused?pausedRemainingMs:deadline-Date.now())/1000));
const clock=n=>[Math.floor(n/60),n%60].map(v=>String(v).padStart(2,'0')).join(':');
function complete(q,a){return Array.isArray(a)&&a.filter(Boolean).length===((q.type==='단일 선택'||q.type==='코드 빈칸')?1:q.keys.length);}
function correct(q,a){if(!Array.isArray(a)||a.length!==q.keys.length)return false;if(q.type==='복수 선택')return [...a].sort().join('|')===[...q.keys].sort().join('|');return a.every((x,i)=>x===q.keys[i]);}
function choose(id){if(!active||paused)return;const q=exams[selected].questions[current];if((q.type==='단일 선택'||q.type==='코드 빈칸'))answers[current]=[id];else{let a=answers[current];if(a.includes(id))answers[current]=a.filter(x=>x!==id);else if(a.length<q.keys.length)a.push(id);else{document.getElementById('answer-note').textContent=`${q.keys.length}개까지 선택할 수 있습니다. 기존 선택을 해제해 주세요.`;return;}}exam(false);}
function assign(index,value){if(!active||paused)return;answers[current][index]=value;exam(false);}
function moveQuestion(i){if(!active||paused)return;current=i;exam();}
function toggleFlag(){if(!active||paused)return;flags.has(current)?flags.delete(current):flags.add(current);exam(false);}
function inputUI(q,a){if(q.type==='매칭')return '<div class="matching-cards">'+q.items.map((item,i)=>{const o=choicesFor(q).find(o=>o.id===a[i]);return '<section class="matching-card"><div class="matching-card-head"><strong>'+tr('상황 ','Situation ')+itemLabel(item.id)+'</strong><span>'+tr(o?'선택 완료':'미응답',o?'Answered':'Not answered')+'</span></div><div class="matching-situation">'+inline(item.text)+'</div><button class="answer-picker" id="answer-picker-'+i+'" aria-haspopup="dialog" aria-label="'+esc(tr('상황 ','Situation ')+itemLabel(item.id)+tr(' 답 선택',' — choose an answer'))+'" onclick="showAnswerPicker('+i+')"><span>'+(o?'✓ '+esc(answerOptionText(q,o)):tr('보기 선택하기','Choose an option'))+'</span><span aria-hidden="true">⌄</span></button></section>';}).join('')+'</div>';if((q.type==='단일 선택'||q.type==='코드 빈칸')||q.type==='복수 선택')return `<div class="options">${choicesFor(q).map((o,optionIndex)=>`<button class="option ${a.includes(o.id)?'selected':''}" aria-pressed="${a.includes(o.id)}" onclick="choose('${o.id}')"><span>${String.fromCharCode(65+optionIndex)}</span><div>${inline(attemptText(q,o.text,false))}</div></button>`).join('')}</div>`;return '<div class="structured-input">'+q.items.map((item,i)=>{const selectedOption=choicesFor(q).find(o=>o.id===a[i]);return '<div class="answer-row"><span>'+esc(q.type==='순서 배열'?tr((i+1)+'번째 단계','Step '+(i+1)):q.type==='매칭'?tr('상황 ','Situation ')+itemLabel(item.id):tr('진술 ','Statement ')+itemLabel(item.id))+'<small>'+(q.type==='진술 판정'?inline(item.text):'')+'</small></span><button class="answer-picker" id="answer-picker-'+i+'" aria-haspopup="dialog" aria-label="'+esc(typeLabel(q.type)+' '+(i+1)+tr('번 답',' answer'))+'" onclick="showAnswerPicker('+i+')"><span>'+esc(selectedOption?answerOptionText(q,selectedOption):tr('선택하세요','Select an answer'))+'</span><span aria-hidden="true">⌄</span></button></div>';}).join('')+'</div>';}
function exam(scroll=true){if(!active)return;if(paused){renderPaused();return;}view='exam';const e=exams[selected],q=e.questions[current],n=e.questions.length,a=answers[current],done=e.questions.filter((q,i)=>complete(q,answers[i])).length;go(`<div class="wrap section"><div class="exam-head"><div><div class="eyebrow" style="color:#777a70;margin-bottom:9px">${e.code} · ${modeLabel()}</div><h2>${esc(e.name)}</h2>${candidateName?`<div class="candidate-chip">${tr('응시자','Candidate')} <strong>${esc(candidateName)}</strong></div>`:''}<span class="sub">${n}문항 · 합격 ${e.threshold}% · 답안 ${done}/${n}</span></div><div class="timer"><small style="display:block;font-size:10px;letter-spacing:0;margin-bottom:5px">남은 시간</small><span id="time">${clock(secondsLeft())}</span><button class="smallbtn full" style="margin-top:10px" onclick="pauseExam()">${tr('일시정지','Pause exam')}</button></div></div><div class="exam-grid"><section class="panel"><div class="question-top"><b>QUESTION ${String(current+1).padStart(2,'0')} / ${n}</b><button class="smallbtn" onclick="toggleFlag()">${flags.has(current)?'⚑ 검토 표시됨':'⚐ 나중에 검토'}</button></div><div class="progress"><i style="width:${(current+1)/n*100}%"></i></div><div class="question-meta">${typeLabel(q.type)}</div>${q.context?`<details class="case-study" open><summary>공통 지문</summary><div class="markdown">${md(q.context)}</div></details>`:''}<div class="markdown question-body">${questionPrompt(q)}</div><p class="answer-note" id="answer-note" role="status">${q.type==='복수 선택'?`정답 ${q.keys.length}개를 선택하세요.`:(q.type==='단일 선택'||q.type==='코드 빈칸')?'가장 적절한 답을 하나 선택하세요.':q.type==='순서 배열'?'첫 단계부터 마지막 단계까지 순서대로 선택하세요.':'각 항목의 답을 모두 선택하세요.'}</p>${inputUI(q,a)}<div class="exam-actions"><button class="btn secondary" ${current===0?'disabled':''} onclick="moveQuestion(${current-1})">← 이전 문제</button>${current<n-1?`<button class="btn dark" onclick="moveQuestion(${current+1})">다음 문제 →</button>`:'<button class="btn" onclick="submit()">제출하고 결과 보기 →</button>'}</div></section><aside class="panel exam-sidebar"><details class="exam-navigation"><summary>${tr('문제 탐색','Question navigator')} · ${done}/${n}</summary><div class="numbers">${e.questions.map((q,i)=>`<button aria-label="${i+1}번 문제${flags.has(i)?', 검토 표시':''}" class="num ${complete(q,answers[i])?'done':''} ${i===current?'current':''} ${flags.has(i)?'flag':''}" onclick="moveQuestion(${i})">${i+1}</button>`).join('')}</div><p class="note">■ 응답 완료　□ 미응답 · 응답 중<br><span style="color:#b96d52">━</span> 나중에 검토</p></details><hr><p class="note">제출 전에는 답을 변경할 수 있습니다. 미응답과 일부만 맞은 답은 오답으로 처리됩니다.</p><button class="btn secondary full" onclick="submit()">시험 제출</button><button class="smallbtn full" onclick="home()">시험 나가기</button></aside></div></div>`,'exams',scroll);}
function questionPoints(q){if(q.points===1)return 1;return {L1:1,L2:2,L3:3,L4:4}[q.difficulty]||1;}
function grade(e,aa){const outcomes=e.questions.map((q,i)=>correct(q,aa[i])),count=outcomes.filter(Boolean).length,totalPoints=e.questions.reduce((n,q)=>n+questionPoints(q),0),earnedPoints=e.questions.reduce((n,q,i)=>n+(outcomes[i]?questionPoints(q):0),0);return {scoringVersion:e.scoring==='equal'?'equal-v1':'difficulty-v1',outcomes,count,total:e.questions.length,totalPoints,earnedPoints,score:Math.round(earnedPoints/totalPoints*100),pass:earnedPoints*100>=e.threshold*totalPoints};}
function domainPerformance(e,r,domain){const ids=e.questions.map((q,i)=>q.domain===domain?i:-1).filter(i=>i>=0),weight=q=>r.scoringVersion==='difficulty-v1'?questionPoints(q):1,total=ids.reduce((n,i)=>n+weight(e.questions[i]),0),earned=ids.reduce((n,i)=>n+(r.outcomes[i]?weight(e.questions[i]):0),0);return {count:ids.filter(i=>r.outcomes[i]).length,questions:ids.length,earned,total,score:total?Math.round(earned/total*100):0};}
function submit(expired=false,confirmed=false){if(!active||paused)return;const e=exams[selected],missing=e.questions.filter((q,i)=>!complete(q,answers[i])).length;if(!expired&&!confirmed){showSiteModal({title:tr('답안을 제출하시겠어요?','Submit your answers?'),message:(missing?tr('미완료 문항이 '+missing+'개 있습니다. ','You have '+missing+' unanswered or incomplete questions. '):'')+tr('제출 후에는 답안을 수정할 수 없으며 결과와 해설을 확인할 수 있습니다.','After submitting, you cannot change your answers. Your results and explanations will be available.'),confirmLabel:tr('제출하고 결과 보기','Submit and view results'),cancelLabel:tr('계속 풀기','Continue exam'),onConfirm:()=>submit(false,true)});return;}closeSiteModal();stop();active=false;lastResult={...grade(e,answers),exam:selected,mode:examMode,candidateName,questionOrder:[...questionOrder],choiceOrder:JSON.parse(JSON.stringify(choiceOrder)),elapsed:durationMinutes()*60-secondsLeft(),answers:answers.map(a=>[...a]),expired};result();}
function renderResult(){if(!lastResult)return;const r=lastResult,e=exams[r.exam];go(`<div class="wrap"><section class="result-hero"><div class="eyebrow" style="color:#777a70">${r.mode==='full'?'YOUR EXAM RESULT':'YOUR DEMO REPORT'}</div><div class="status-icon" style="${r.pass?'':'background:#f3e6dd;color:#a76a4e'}">${r.pass?'✓':'↗'}</div><span class="level">${r.pass?'PASSED · 합격':'NOT PASSED · 불합격'}</span><h1>${r.mode==='full'&&r.pass?tr('자격증 취득을 축하합니다.','You earned your certification.'):r.pass?'잘 해내셨어요. 다음 단계로 나아가세요.':'한 걸음 더, 목표에 가까워지고 있어요.'}</h1><p class="candidate-result">${r.candidateName?esc(r.candidateName)+tr(' 님의 시험 결과',' · Exam result'):''}</p><p class="sub">${e.code} · ${esc(certificationName(e))}<br>${r.total}문항 ${modeLabel(r.mode)} 결과${r.expired?' · 시간 종료로 자동 제출':''}</p></section><details class="share-panel"><summary class="share-summary"><span class="share-summary-title"><div class="eyebrow" style="color:#9d6650;margin-bottom:10px">SHARE YOUR PROGRESS</div><h2>오늘의 도전을 나눠보세요.</h2><p class="sub">나의 학습 기록을 SNS와 LinkedIn에 공유하세요.</p></span><span class="share-chevron" aria-hidden="true">⌄</span></summary><div class="share-content"><div class="share-preview report-preview"><img id="report-preview" alt="자격증 배지와 영역별 정답률이 포함된 공유 성적표" hidden><span id="report-loading" role="status">공유 성적표를 준비하고 있습니다…</span></div><div class="share-buttons"><button id="linkedin-prepare" class="btn dark" onclick="shareLinkedIn()">in &nbsp; LinkedIn에 공유</button><a id="linkedin-open" class="btn dark" target="_blank" rel="noopener noreferrer" hidden>${tr('LinkedIn 공유 창 열기 ↗','Open LinkedIn share dialog ↗')}</a><button class="btn secondary" onclick="shareSocial()">↗ SNS 공유</button><button class="btn secondary" onclick="copyShareLink()">${tr('공유 링크 복사','Copy share link')}</button><button class="btn secondary" onclick="copyResult()">공유 문구 복사</button><button class="btn secondary" onclick="downloadCard()">결과 이미지 저장</button></div><p id="share-status" class="note" role="status" aria-live="polite">${r.mode==='full'&&r.pass?tr('자격증 취득 결과를 링크로 공유하세요.','Share your certification achievement with a link.'):tr('이번 응시 기록을 공유하세요.','Share your exam progress.')}</p><a id="share-link" class="smallbtn" target="_blank" rel="noopener noreferrer" hidden></a><textarea id="share-copy" readonly aria-label="공유 문구" hidden></textarea></div></details><div class="result-grid"><section class="panel score"><div class="side-title">종합 점수 <span class="code">SCORE</span></div><div class="score-ring" style="--pct:${r.score}%;background:conic-gradient(${r.pass?'#748872':'#b77d61'} ${r.score}%,#eae8de 0)"><div><strong>${r.score}<span style="font-size:17px">점</span></strong><small>100점 만점</small></div></div><p class="sub">합격 기준 <b>${e.threshold}%</b></p>${r.scoringVersion==='difficulty-v1'?`<p class="note">${tr('획득 점수','Points earned')} <b>${r.earnedPoints} / ${r.totalPoints}</b></p>`:''}<div class="score-info"><div><b>${r.count}/${r.total}</b>정답 문항</div><div><b>${clock(r.elapsed)}</b>소요 시간</div></div><button class="btn dark full" onclick="start(${r.exam},'${r.mode||'demo'}')">다시 도전하기 →</button><button class="smallbtn full" onclick="detail(${r.exam})">시험 가이드 확인</button><button class="smallbtn full" onclick="home()">자격증 둘러보기</button></section><section class="panel"><h2 style="font-size:19px">영역별 학습 현황</h2><p class="sub">${e.scoring==='equal'?tr('영역별 정답 문항 / 출제 문항 · 동일 배점','Correct / total questions in each domain · Equal weighting'):tr('영역별 획득 점수 / 총 배점 · 난이도 배점 반영','Points earned / available in each domain · Weighted by difficulty')}</p>${e.domains.map(d=>{const stats=domainPerformance(e,r,d.id),v=stats.score;return `<div class="domain"><div><span>${esc(d.name)}</span><b>${stats.questions?`${stats.earned}/${stats.total} · ${v}%`:'출제 문항 없음'}</b></div><div class="progress"><i style="width:${v}%"></i></div></div>`;}).join('')}<p class="note">${e.scoring==='equal'?tr('문항당 동일 배점 · 모든 답이 일치해야 득점하며, 오답 감점은 없습니다.','Each question carries equal weight. All parts must be correct; there is no penalty for incorrect answers.'):tr('난이도별 1–4점 · 복합 문항은 전체 일치 시 득점','1–4 points by difficulty · All parts must be correct')}<br>${e.scoring==='equal'?tr('정규 시험은 60문항 중 42문항 이상 정답이면 합격합니다.','Pass the full exam by answering at least 42 of 60 questions correctly.'):tr('합격 판정은 반올림 전 배점 환산 점수를 기준으로 합니다.','Pass/fail uses the unrounded weighted score.')}</p></section></div><section class="review-section panel"><div class="section-head"><div><h2>문제별 복습</h2><p class="sub">내 답안, 정답, 상세 해설과 근거 문서를 확인하세요.</p><p class="note">보기 순서와 해설의 기호는 응시 화면과 동일합니다.</p></div><div class="tabs"><button class="tab ${reviewFilter==='all'?'selected':''}" onclick="reviewFilter='all';result();document.getElementById('reviews').scrollIntoView()">전체 ${r.total}</button><button class="tab ${reviewFilter==='wrong'?'selected':''}" onclick="reviewFilter='wrong';result();document.getElementById('reviews').scrollIntoView()">오답 ${r.total-r.count}</button></div></div><div id="reviews">${e.questions.map((q,i)=>reviewFilter==='wrong'&&r.outcomes[i]?'':`<details class="review"><summary><span class="review-status ${r.outcomes[i]?'ok':'wrong'}">${r.outcomes[i]?'정답':'오답'}</span> Q${String(i+1).padStart(2,'0')}. ${esc(q.title)}</summary><p class="review-meta note">${tr('출제 영역','Domain')} · ${esc(e.domains.find(d=>d.id===q.domain)?.name||String(q.domain))} <span> | ${tr('배점','Points')} ${questionPoints(q)}</span></p><div class="answer-comparison"><span>내 답안 <b>${esc(formatAnswer(q,r.answers[i]))}</b></span><span>정답 <b>${esc(formatAnswer(q,q.keys))}</b></span></div><div class="markdown">${q.context?'<h3>공통 지문</h3>'+md(q.context):''}${questionPrompt(q)}${q.options.length&&['코드 빈칸','단일 선택','복수 선택'].includes(q.type)?'<ul>'+choicesFor(q).map(o=>`<li><b>${optionLabel(q,o.id)}.</b> ${inline(attemptText(q,o.text,false))}</li>`).join('')+'</ul>':''}<h3>상세 해설</h3>${md(attemptExplanation(q))}</div></details>`).join('')}${reviewFilter==='wrong'&&r.count===r.total?'<p class="sub">모든 문항을 맞혔습니다.</p>':''}</div></section></div>`);}

function optionLabel(q,id){const index=choicesFor(q).findIndex(o=>o.id===id);return index<0?id:String.fromCharCode(65+index);}
function attemptExplanation(q){const text=attemptText(q,q.explanation);if(!['코드 빈칸','단일 선택','복수 선택'].includes(q.type))return text;const lines=text.split('\n'),label=line=>line.match(/^\s*-\s+(?:\*\*)?([A-Z])(?=[\s.:：)（(])/);for(let i=0;i<lines.length;i++){if(!label(lines[i]))continue;let end=i,rows=[];while(end<lines.length&&(label(lines[end])||!lines[end].trim())){if(label(lines[end]))rows.push(lines[end]);end++;}const ids=rows.map(row=>label(row)[1]);if(rows.length===q.options.length&&new Set(ids).size===rows.length&&ids.every(id=>id>='A'&&id<String.fromCharCode(65+q.options.length))){const sorted=rows.slice().sort((a,b)=>label(a)[1].localeCompare(label(b)[1]));let next=0;for(let j=i;j<end;j++)if(label(lines[j]))lines[j]=sorted[next++];}i=end-1;}return lines.join('\n');}
function attemptText(q,text,legacy=true){
 if(text.includes('{{option:'))return text.replace(/\{\{option:([A-Za-z가-힣])\}\}/g,(_,id)=>['코드 빈칸','단일 선택','복수 선택'].includes(q.type)?optionLabel(q,id):q.type==='매칭'?matchingLabel(q,id):itemLabel(id));
 if(q.format==='code-fill'||!legacy||!['코드 빈칸','단일 선택','복수 선택'].includes(q.type))return text;
 // Protect code and link destinations; replace all references in one pass.
 return text.replace(/```[\s\S]*?```|`[^`]*`|https?:\/\/[^\s)]+|(?<![A-Za-z0-9_&/=-])[A-Z](?![A-Za-z0-9_&/=-])/g,(token,offset,text)=>{
  if(!/^[A-Z]$/.test(token)||!q.options.some(o=>o.id===token))return token;
  // English A can be an article. Actual option references use predicates,
  // coordination, possessives, or punctuation (including Markdown headings).
  if(window.APP_LANG==='en'&&token==='A'&&!/^(?:\s*(?:[(*),.;:|]|$)|['’]s\b|\s+(?:and|or|respectively|also|directly|addresses|spends|meets|satisfies|is|was|would|violates|fails|requires|provides|uses|does|only|cannot|can)\b)/.test(text.slice(offset+1)))return token;
  return optionLabel(q,token);
 });
}

function formatAnswer(q,a){if(!a?.some(Boolean))return '미응답';if(q.type==='매칭'||q.type==='진술 판정')return q.items.map((x,i)=>itemLabel(x.id)+': '+(a[i]?(q.type==='매칭'?matchingLabel(q,a[i]):itemLabel(a[i])):'미응답')).join(', ');if(q.type==='순서 배열')return q.items.map((_,i)=>a[i]?'('+itemLabel(a[i])+')':'미응답').join(' → ');return a.map(id=>optionLabel(q,id)).sort().join(', ');}
function shareText(r=lastResult){if(!r)return '';const e={...exams[r.exam],name:certificationName(exams[r.exam])},earned=r.mode==='full'&&r.pass;return (earned?tr(e.name+'을 취득하였습니다.','I earned the '+e.name+' certification.'):tr('AIpath '+e.name+' '+modeLabel(r.mode)+'에 응시했습니다.','I completed the '+e.name+' '+modeLabel(r.mode).toLowerCase()+' on AIpath.'))+'\n'+r.count+'/'+r.total+tr('문항 정답 · ',' correct · ')+r.score+'/100\n#AIpath #GenerativeAI #AILearning';}
function shareStatus(message){const el=document.getElementById('share-status');if(el)el.textContent=message;}
async function copyResult(){if(!lastResult)return false;try{await navigator.clipboard.writeText(shareText());shareStatus('공유 문구를 복사했습니다. 게시글에 붙여넣어 주세요.');return true;}catch{const box=document.getElementById('share-copy');if(box){box.hidden=false;box.value=shareText();box.focus();box.select();}shareStatus('아래 선택된 문구를 직접 복사해 주세요.');return false;}}
const reportCache=new WeakMap();
function loadReportImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('배지 이미지를 불러오지 못했습니다.'));img.src=src;});}
function result(){view='result';renderResult();const r=lastResult;if(!r)return;getReport(r).then(asset=>{if(lastResult!==r)return;const img=document.getElementById('report-preview'),loading=document.getElementById('report-loading');if(img){img.src=asset.url;img.hidden=false;}if(loading)loading.hidden=true;}).catch(()=>{const loading=document.getElementById('report-loading');if(loading)loading.textContent='성적표를 불러오지 못했습니다. 이미지 저장을 눌러 다시 시도해 주세요.';});}
function getReport(r=lastResult){if(!r)return Promise.reject(new Error('시험 결과가 없습니다.'));if(!reportCache.has(r)){const task=buildReport(r).catch(error=>{reportCache.delete(r);throw error;});reportCache.set(r,task);}return reportCache.get(r);}
async function buildReport(r){
 const metadata=exams[r.exam],byId=new Map(originalQuestions[r.exam].map(q=>[q.id,q])),e={...metadata,name:certificationName(metadata),questions:r.questionOrder.map(id=>byId.get(id))};
 if(document.fonts){await Promise.all([document.fonts.load('400 22px Pretendard'),document.fonts.load('600 31px Pretendard'),document.fonts.load('700 64px Inter')]);await document.fonts.ready;}
 const [badge,mark]=await Promise.all([loadReportImage('badges/'+e.code+'-symbol.svg'),loadReportImage('brand-lockup-bronze.svg')]);
 const canvas=document.createElement('canvas');canvas.width=1200;canvas.height=630;const c=canvas.getContext('2d');
 const ink='#292a27',muted='#77736c',accent=r.pass?'#5c7353':'#a27355',earned=r.mode==='full'&&r.pass;
 function text(t,x,y,size=22,color=ink,weight=400){c.fillStyle=color;c.font=weight+' '+size+'px Inter,Pretendard,sans-serif';c.fillText(t,x,y);}
 function box(x,y,w,h,fill){c.fillStyle=fill;c.beginPath();c.roundRect(x,y,w,h,8);c.fill();}
 function fit(t,x,y,width,size=30){while(size>12){c.font='600 '+size+'px Inter,Pretendard,sans-serif';if(c.measureText(t).width<=width)break;size--;}text(t,x,y,size,ink,600);}
 c.fillStyle='#f8f6f1';c.fillRect(0,0,1200,630);c.strokeStyle='#ded9ce';c.lineWidth=1;c.strokeRect(18,18,1164,594);
 c.drawImage(mark,52,42,174,42);
 if(r.candidateName)fit(tr('응시자 · ','CANDIDATE · ')+r.candidateName,342,99,790,19);
 c.drawImage(badge,53,122,240,240);text(modeLabel(r.mode),342,128,17,muted,500);
 const words=e.name.split(' ');let line='',lines=[];c.font='600 33px Inter,Pretendard,sans-serif';for(const word of words){const next=(line?line+' ':'')+word;if(c.measureText(next).width>790&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);lines.slice(0,2).forEach((t,i)=>fit(t,342,173+i*40,790,33));
 text(earned?tr('자격증을 취득하였습니다.','Certification earned.'):r.pass?tr('합격 기준을 달성했습니다.','Passing score achieved.'):tr('다음 도전을 위한 학습 기록','Your progress toward the next attempt'),342,239,22,accent,600);
 box(342,266,790,100,'#eeece5');text(String(r.score),365,332,53,ink,600);text('/100',455,331,20,muted);text(tr('정답 문항','Correct answers'),576,295,14,muted);text(r.count+' / '+r.total,576,333,27,ink,600);text(tr('소요 시간','Time taken'),800,295,14,muted);text(clock(r.elapsed),800,333,27,ink,600);text(r.pass?'PASS':'RETRY',1000,327,18,accent,600);
 text(tr('영역별 역량 · 획득 점수 / 배점','DOMAIN PERFORMANCE · POINTS EARNED / AVAILABLE'),55,405,16,muted,600);
 e.domains.forEach((d,j)=>{const stats=domainPerformance(e,r,d.id),n=stats.total,k=stats.earned,p=stats.score,x=j%2?630:55,y=442+Math.floor(j/2)*52;fit(d.name,x,y,400,16);text(n?k+'/'+n+' · '+p+'%':'—',x+452,y,14,muted);box(x,y+11,500,6,'#e3dfd6');if(p)box(x,y+11,500*p/100,6,accent);});
 const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image generation failed')),'image/png'));
 const filename='AIpath-'+e.code+'-'+r.mode+'-'+window.APP_LANG+'.png';return {blob,file:new File([blob],filename,{type:'image/png'}),url:URL.createObjectURL(blob),filename};
}

function saveReport(asset){const a=document.createElement('a');a.href=asset.url;a.download=asset.filename;a.click();}
async function downloadCard(){if(!lastResult)return;try{saveReport(await getReport());shareStatus('화면에 보이는 성적표와 동일한 PNG를 저장했습니다.');}catch{shareStatus('이미지 생성에 실패했습니다. 다시 시도해 주세요.');}}
async function shareSocial(){if(!lastResult)return;try{const asset=await getReport();if(navigator.share&&navigator.canShare?.({files:[asset.file]})){await navigator.share({title:tr('AIpath 시험 성적표','AIpath exam report'),text:shareText(),files:[asset.file]});shareStatus('성적표 이미지를 공유 창에 전달했습니다.');}else{saveReport(asset);await copyResult();shareStatus('이 브라우저는 이미지 직접 공유를 지원하지 않아 동일한 성적표를 저장했습니다. SNS에 이미지를 첨부해 주세요.');}}catch(e){if(e.name!=='AbortError')shareStatus('공유를 완료하지 못했습니다. 이미지 저장 후 SNS에 첨부해 주세요.');}}
async function shareLinkedIn(){const r=lastResult,button=document.getElementById('linkedin-prepare');if(!r||button?.disabled)return;if(button){button.disabled=true;button.setAttribute('aria-busy','true');}shareStatus(tr('공유 링크를 준비하고 있습니다…','Preparing your share link…'));try{const url=await getShareLink(r);if(lastResult!==r||view!=='result')return;const a=document.getElementById('linkedin-open');if(a){a.href='https://www.linkedin.com/sharing/share-offsite/?url='+encodeURIComponent(url);a.hidden=false;const currentButton=document.getElementById('linkedin-prepare');if(currentButton)currentButton.hidden=true;a.focus();}shareStatus(tr('준비되었습니다. «LinkedIn 공유 창 열기»를 눌러 게시물을 확인하세요.','Ready. Select “Open LinkedIn share dialog” to review your post.'));}catch(error){if(lastResult===r&&view==='result')shareStatus(tr('공유 링크를 만들지 못했습니다. 잠시 후 다시 시도해 주세요.','Could not create the share link. Please try again shortly.'));}finally{if(button){button.disabled=false;button.removeAttribute('aria-busy');}}}


window.addEventListener('beforeunload',event=>{if(active&&!languageSwitchPending&&!window.REVIEW_PREVIEW){event.preventDefault();event.returnValue='';}});

const courseRequests=new Map();
function ensureCourse(i){
 if(originalQuestions[i].length)return Promise.resolve();
 if(!courseRequests.has(i)){
  const task=fetch('courses/'+window.APP_LANG+'/'+exams[i].code+'.json?v=bank-20261020').then(r=>{if(!r.ok)throw Error('Course unavailable');return r.json();}).then(data=>{if(!Array.isArray(data.questions)||data.questions.length!==exams[i].bankCount||typeof data.guide!=='string')throw Error('Invalid course');originalQuestions[i]=data.questions;exams[i].questions=data.questions.slice();exams[i].guide=data.guide;}).catch(error=>{courseRequests.delete(i);throw error;});
  courseRequests.set(i,task);
 }
 return courseRequests.get(i);
}
function loadCourseView(i,resume){
 go('<section class="wrap section"><div class="panel" role="status" aria-live="polite"><div class="eyebrow">'+esc(exams[i].code)+'</div><h2>'+tr('시험 자료를 준비하고 있습니다','Preparing your exam materials')+'</h2><p class="sub">'+tr('선택한 자격증의 문제와 해설을 불러오고 있습니다.','Loading questions and explanations for your selected certification.')+'</p><div class="loading-bars" aria-hidden="true"><i></i><i></i><i></i></div></div></section>');
 const epoch=renderEpoch;
 return ensureCourse(i).then(()=>{if(epoch===renderEpoch)resume();}).catch(()=>{if(epoch!==renderEpoch)return;go('<section class="wrap section"><div class="panel" role="alert"><h2>'+tr('자료를 불러오지 못했습니다','Could not load the materials')+'</h2><p>'+tr('연결 상태를 확인하고 다시 시도해 주세요.','Check your connection and try again.')+'</p><button id="retry-course" class="btn">'+tr('다시 시도','Try again')+'</button> <button class="btn secondary" onclick="home()">'+tr('자격증 둘러보기','Explore certifications')+'</button></div></section>');document.getElementById('retry-course').onclick=()=>loadCourseView(i,resume);});
}

if(!window.REVIEW_PREVIEW)restoreLanguageState();

function startTimer(){stop();if(paused||!active)return;timer=setInterval(()=>{const remaining=secondsLeft();const t=document.getElementById('time');if(t)t.textContent=clock(remaining);if(remaining<=0)submit(true);},1000);}

function changeLanguage(lang){if(lang===window.APP_LANG)return;const state={version:2,paused,pausedRemainingMs,examMode,candidateName,registrationName,view,selected,current,answers,questionOrder,choiceOrder,flags:[...flags],deadline,lastResult,active,filter,reviewFilter};try{sessionStorage.setItem('aipath-language-state',JSON.stringify(state));localStorage.setItem('aipath-language',lang);}catch{document.getElementById('language-select').value=window.APP_LANG;showSiteModal({title:tr('언어를 변경하지 못했습니다','Language change failed'),message:window.APP_LANG==='en'?'Your browser could not save the language change. Please allow site storage and try again.':'언어 변경을 저장하지 못했습니다. 브라우저의 사이트 저장을 허용하고 다시 시도해 주세요.'});return;}languageSwitchPending=true;stop();const url=new URL(location.href);url.searchParams.set('lang',lang);location.replace(url.href);}
function restoreLanguageState(savedState){let state=savedState||null;if(!state)try{state=JSON.parse(sessionStorage.getItem('aipath-language-state'));sessionStorage.removeItem('aipath-language-state');}catch{}if(state?.version===2&&exams[state.selected]&&(state.active||state.view==='result'||state.view==='detail')&&!originalQuestions[state.selected].length){return loadCourseView(state.selected,()=>restoreLanguageState(state));}if(state?.version===2&&Number.isInteger(state.selected)&&exams[state.selected]){({selected,current,answers,deadline,lastResult,active,filter,reviewFilter,examMode}=state);paused=state.paused===true;pausedRemainingMs=Math.max(0,Math.min(Number(state.pausedRemainingMs)||0,durationMinutes()*60000));candidateName=state.candidateName||state.lastResult?.candidateName||'';registrationName=state.registrationName||candidateName;flags=new Set(state.flags);questionOrder=state.questionOrder||originalQuestions[selected].map(q=>q.id);choiceOrder=state.choiceOrder||{};if(active||state.view==='result')applyQuestionOrder(selected);if(state.view==='enroll'||state.view==='confirm'){enroll(selected,state.view==='confirm');return;}if(state.view==='exams'){examCatalog();return;}if(active){if(paused){renderPaused();return;}if(secondsLeft()<=0){submit(true);return;}exam();startTimer();return;}if(state.view==='result'&&lastResult){result();return;}if(state.view==='detail'){detail(selected);return;}home(filter);return;}home();}
function itemLabel(id){return window.APP_LANG==='en'?({'가':'1','나':'2','다':'3','라':'4','마':'5','바':'6','사':'7','아':'8','자':'9','차':'10'}[id]||id):id;}
function typeLabel(type){return window.APP_LANG==='en'?({'코드 빈칸':'Code completion','단일 선택':'Single choice','복수 선택':'Multiple select','매칭':'Matching','순서 배열':'Ordering','진술 판정':'Yes / No'}[type]||type):type;}

function shuffled(values){const result=values.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
function choicePool(q){return q.type==='진술 판정'?[{id:'Yes',text:tr('Yes · 맞음','Yes · True')},{id:'No',text:tr('No · 틀림','No · False')}]:q.type==='순서 배열'?q.items:q.options;}
function randomizeAttempt(index){const size=examMode==='full'?exams[index].count:10;questionOrder=exams[index].code==='ASF'?sampleASP(originalQuestions[index],examMode):shuffled(originalQuestions[index].map(q=>q.id)).slice(0,size);choiceOrder=Object.fromEntries(originalQuestions[index].filter(q=>questionOrder.includes(q.id)).map(q=>[q.id,shuffled(choicePool(q).map(o=>o.id))]));applyQuestionOrder(index);}
function applyQuestionOrder(index){const pool=originalQuestions[index],byId=new Map(pool.map(q=>[q.id,q])),size=examMode==='full'?exams[index].count:10;if(questionOrder.length!==size||new Set(questionOrder).size!==size||questionOrder.some(id=>!byId.has(id)))throw new Error('Invalid attempt question order');exams[index].questions=questionOrder.map(id=>byId.get(id));}
function choicesFor(q){const pool=choicePool(q),order=choiceOrder[q.id];if(!order||order.length!==pool.length||new Set(order).size!==pool.length||order.some(id=>!pool.some(o=>o.id===id)))return pool;return order.map(id=>pool.find(o=>o.id===id));}


function examCatalog(){if(!leave(()=>examCatalog()))return;view='exams';go(`<section class="wrap section exam-center"><div class="enroll-heading"><div class="eyebrow">AIPATH CERTIFICATION EXAMS</div><h1>${tr('시험 응시하기','Take an exam')}</h1><p class="sub">${tr('당신의 전문성을 확인하는 다음 단계. 응시할 자격증을 선택해 주세요.','Your next step toward demonstrating expertise. Select your certification to begin.')}</p></div>${registrationSteps(1)}<div class="exam-list">${catalogEntries().map(({e,i})=>`<article class="exam-list-row"><img src="badges/${e.code}-symbol.svg" alt="${esc(certificationName(e))}"><div class="exam-list-info"><span class="code">${e.code} <span> / ${e.level.toUpperCase()}</span></span><h2>${esc(certificationName(e))}</h2><p>${e.count}${tr('문항',' questions')} <span> · </span> ${e.minutes}${tr('분',' minutes')} <span> · </span> ${tr('합격 기준','Pass mark')} ${e.threshold}%</p></div><button class="btn dark" onclick="start(${i},'full')" aria-label="${e.code} ${tr('응시 등록','Register for exam')}">${tr('응시 등록','Register')} <span aria-hidden="true">↗</span></button></article>`).join('')}</div><p class="note enrollment-foot">${tr('먼저 경험해 보고 싶으신가요? 자격증 둘러보기에서 10문항 데모 시험을 이용하세요.','Want to try it first? Explore certifications for a 10-question demo exam.')}</p></section>`,'exams');}

function getShareLink(r=lastResult){if(!shareCache.has(r)){const promise=(async()=>{const asset=await getReport(r),form=new FormData();form.append('image',asset.blob,asset.filename);form.append('result',JSON.stringify({code:exams[r.exam].code,scoringVersion:r.scoringVersion,candidateName:r.candidateName||'',mode:r.mode,lang:window.APP_LANG,questionOrder:r.questionOrder,answers:r.answers,elapsed:r.elapsed}));const response=await fetch('/api/share',{method:'POST',headers:{'X-AIpath-Share':'1'},body:form});if(!response.ok)throw Error('Share failed');const data=await response.json();return data.url;})().catch(error=>{shareCache.delete(r);throw error;});shareCache.set(r,promise);}return shareCache.get(r);}

async function copyShareLink(){const r=lastResult;if(!r)return;shareStatus(tr('공유 링크를 준비하고 있습니다…','Preparing your share link…'));try{const url=await getShareLink(r);const a=document.getElementById('share-link');if(a){a.href=url;a.textContent=tr('공유 결과 열기','Open shared result');a.hidden=false;}try{await navigator.clipboard.writeText(url);shareStatus(tr('공유 링크를 복사했습니다.','Share link copied.'));}catch{const box=document.getElementById('share-copy');box.hidden=false;box.value=url;box.focus();box.select();shareStatus(tr('아래 링크를 복사해 주세요.','Copy the link below.'));}}catch{shareStatus(tr('공유 링크를 만들지 못했습니다. 다시 시도해 주세요.','Could not create the share link. Please try again.'));}}


function registrationSteps(step){return '<ol class="registration-steps" aria-label="'+tr('시험 접수 단계','Exam registration steps')+'">'+[tr('시험 선택','Select exam'),tr('응시자 정보','Candidate details'),tr('최종 확인','Review & begin')].map((label,i)=>'<li class="'+(i+1===step?'current':i+1<step?'complete':'')+'" '+(i+1===step?'aria-current="step"':'')+'><span>'+String(i+1).padStart(2,'0')+'</span>'+label+'</li>').join('')+'</ol>';}
function cleanCandidate(value){return String(value||'').normalize('NFC').replace(/[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2060-\u206f]/g,'').replace(/\s+/g,' ').trim();}
function enroll(i=selected,review=false){if(!leave(()=>enroll(i,review)))return;selected=i;view=review?'confirm':'enroll';const e=exams[i];go(`<section class="wrap section exam-center"><button class="smallbtn enrollment-back" onclick="${review?'enroll('+i+')':'examCatalog()'}">← ${review?tr('응시자 정보 수정','Edit candidate details'):tr('시험 목록','All exams')}</button><div class="enroll-heading"><div class="eyebrow">EXAM REGISTRATION</div><h1>${review?tr('응시 내용을 확인해 주세요','Ready when you are'):tr('응시자 정보를 입력해 주세요','Introduce yourself')}</h1><p class="sub">${review?tr('시험 시작 버튼을 누르면 제한 시간이 시작됩니다.','Your exam timer starts only when you select Begin exam.'):tr('시험 결과와 성적표에 표시할 이름을 알려주세요.','Choose the name that will appear on your results and score report.')}</p></div>${registrationSteps(review?3:2)}<div class="registration-grid"><section class="registration-form panel">${review?`<div class="eyebrow">CANDIDATE</div><h2 class="candidate-name">${esc(registrationName)}</h2><p class="sub">${tr('성적표에 표시되는 이름입니다.','This is the name shown on your score report.')}</p><hr><h3>${tr('시작 전 확인','Before you begin')}</h3><ul class="exam-instructions"><li>${tr('문항과 보기 순서는 매번 무작위로 구성됩니다.','Questions and answer choices are randomized for each attempt.')}</li><li>${e.scoring==='equal'?tr('문항당 동일 배점 · 모든 답이 일치해야 득점하며, 오답 감점은 없습니다.','Each question carries equal weight. All parts must be correct; there is no penalty for incorrect answers.'):tr('난이도 L1–L4에 따라 1–4점을 배점하고, 총 배점 대비 100점으로 환산합니다.','Questions carry 1–4 points by difficulty (L1–L4), normalized to a score out of 100.')}</li><li>${tr('제출 전에는 답안을 수정하고 검토 표시를 할 수 있습니다.','You can revise answers and flag questions before submitting.')}</li><li>${tr('제한 시간이 끝나면 현재 답안이 자동으로 제출됩니다.','Your current answers are submitted automatically when time expires.')}</li><li>${tr('시험 도중 창을 닫거나 새로고침하면 응시 기록이 사라질 수 있습니다.','Closing or refreshing the page may discard your attempt.')}</li></ul><button class="btn dark full" onclick="start(${i},'full',true)">${tr('시험 시작','Begin exam')} →</button><p class="note">${tr('지금부터 '+e.minutes+'분 동안 시험을 진행합니다.', 'You will have '+e.minutes+' minutes to complete the exam.')}</p>`:`<form onsubmit="reviewRegistration(event)"><div class="eyebrow">CANDIDATE DETAILS</div><h2>${tr('응시자 정보','Candidate details')}</h2><label class="candidate-label" for="candidate-name">${tr('이름 또는 닉네임','Name or nickname')} <span>${tr('필수','Required')}</span></label><input id="candidate-name" name="candidateName" class="candidate-input" type="text" required maxlength="40" autocomplete="nickname" value="${esc(registrationName)}" placeholder="${tr('성적표에 표시할 이름','Your name on the score report')}" aria-describedby="candidate-help candidate-error" oninput="registrationName=this.value;this.setCustomValidity('')"><p id="candidate-help" class="note">${tr('1–40자로 입력해 주세요. 한글과 영문 모두 사용할 수 있습니다.','Use 1–40 characters. Names in any language are welcome.')}</p><p id="candidate-error" class="field-error" role="alert"></p><div class="name-notice">${tr('입력한 이름은 결과와 성적표에 표시됩니다. 결과를 공유하면 공유 링크와 이미지에도 이름이 공개되므로, 원하는 경우 닉네임을 사용하세요.','Your name appears on your results and score report. If you share your result, it will also be visible on the shared link and image. You may use a nickname.')}</div><button type="submit" class="btn dark full">${tr('입력 내용 확인','Review registration')} →</button></form>`}</section><aside class="registration-summary panel"><div class="eyebrow">YOUR EXAM</div><img src="badges/${e.code}-symbol.svg" alt="${esc(certificationName(e))}"><span class="code">${e.code} / ${e.level.toUpperCase()}</span><h2>${esc(certificationName(e))}</h2><dl><div><dt>${tr('시험 유형','Exam type')}</dt><dd>${tr('정규 시험','Full exam')}</dd></div><div><dt>${tr('문항 수','Questions')}</dt><dd>${e.count}</dd></div><div><dt>${tr('제한 시간','Time limit')}</dt><dd>${e.minutes}${tr('분',' min')}</dd></div><div><dt>${tr('합격 기준','Pass mark')}</dt><dd>${e.threshold}%</dd></div></dl><p class="note">${tr('제출 후 점수, 영역별 역량, 문항별 해설을 확인할 수 있습니다.','After submission, review your score, domain performance, and explanations.')}</p></aside></div></section>`,'exams');}
function reviewRegistration(event){event.preventDefault();const input=document.getElementById('candidate-name'),name=cleanCandidate(input.value);if(!name||name.length>40){const message=tr('이름 또는 닉네임을 1–40자로 입력해 주세요.','Enter a name or nickname using 1–40 characters.');document.getElementById('candidate-error').textContent=message;input.setAttribute('aria-invalid','true');input.focus();return;}registrationName=name;enroll(selected,true);}

function pauseExam(){if(!active||paused)return;const remaining=deadline-Date.now();if(remaining<=0){submit(true);return;}pausedRemainingMs=remaining;paused=true;stop();renderPaused();}
function resumeExam(){if(!active||!paused)return;deadline=Date.now()+pausedRemainingMs;paused=false;pausedRemainingMs=0;exam();startTimer();}
function renderPaused(){view='exam';const e=exams[selected];go('<section class="wrap section"><div class="panel pause-panel" role="status"><div class="eyebrow">'+esc(e.code)+' · '+modeLabel()+'</div><div class="pause-symbol" aria-hidden="true">Ⅱ</div><h1>'+tr('시험이 일시정지되었습니다','Your exam is paused')+'</h1><p class="sub">'+tr('문제와 보기, 선택한 답안을 가렸습니다. 준비되면 이어서 응시하세요.','Questions, choices, and selected answers are hidden. Continue when you are ready.')+'</p><div class="pause-time"><span>'+tr('남은 시간','Time remaining')+'</span><strong>'+clock(secondsLeft())+'</strong></div><button id="resume-exam" class="btn dark" onclick="resumeExam()">'+tr('시험 계속하기','Resume exam')+' →</button><p class="note">'+tr('쉬는 시간은 시험 소요 시간에 포함되지 않습니다.','Breaks do not count toward your exam time.')+'</p><button class="smallbtn" onclick="home()">'+tr('시험 나가기','Exit exam')+'</button></div></section>','exams');document.getElementById('resume-exam')?.focus?.();}

// Keep ASF domain, provider, and question-format quotas while sampling content.
function sampleASP(pool,mode){
 const full=mode==='full',types=['단일 선택','복수 선택','순서 배열','매칭'],groups=['openai','anthropic','google','cross',2,3],sizes=full?[12,12,12,6,12,6]:[2,2,2,1,2,1],target=full?[42,12,3,3]:(Math.random()<.5?[7,2,1,0]:[7,2,0,1]);
 const buckets=groups.map(g=>types.map(t=>shuffled(pool.filter(q=>(typeof g==='number'?q.domain===g:q.provider===g)&&q.type===t))));
 const plans=buckets.map((b,g)=>{const out=[];function enumerate(t,left,counts){if(t===3){if(left>=0&&left<=b[t].length)out.push([...counts,left]);return;}for(let n=0;n<=Math.min(left,b[t].length);n++)enumerate(t+1,left-n,[...counts,n]);}enumerate(0,sizes[g],[]);return shuffled(out);});
 const failed=new Set();function solve(g,remaining){if(g===groups.length)return remaining.every(n=>n===0)?[]:null;const key=g+':'+remaining;if(failed.has(key))return null;for(const counts of plans[g]){const next=remaining.map((n,t)=>n-counts[t]);if(next.some((n,t)=>n<0||n>buckets.slice(g+1).reduce((sum,b)=>sum+b[t].length,0)))continue;const rest=solve(g+1,next);if(rest)return [counts,...rest];}failed.add(key);return null;}
 const allocation=solve(0,target);if(!allocation)throw Error('ASF question quotas cannot be satisfied');return shuffled(allocation.flatMap((counts,g)=>counts.flatMap((n,t)=>buckets[g][t].slice(0,n).map(q=>q.id))));
}

function catalogEntries(){const levels=['Fundamental','Associate','Professional','Specialty'];return exams.map((e,i)=>({e,i})).sort((a,b)=>levels.indexOf(a.e.level)-levels.indexOf(b.e.level));}

var siteModal=null;
function closeSiteModal(){
 if(!siteModal)return;
 const current=siteModal;siteModal=null;
 current.dialog.close();current.dialog.remove();
 if(current.focus?.isConnected)current.focus.focus();
}
function showSiteModal({title,message,confirmLabel=tr('확인','OK'),cancelLabel,onConfirm}){
 if(siteModal)return;
 const focus=document.activeElement,dialog=document.createElement('dialog');
 dialog.className='site-modal';
 dialog.setAttribute('aria-labelledby','site-modal-title');
 dialog.setAttribute('aria-describedby','site-modal-message');
 dialog.innerHTML='<div class="modal-mark" aria-hidden="true">◇</div><h2 id="site-modal-title">'+esc(title)+'</h2><p id="site-modal-message">'+esc(message)+'</p><div class="modal-actions">'+(cancelLabel?'<button class="btn secondary" data-modal-cancel autofocus>'+esc(cancelLabel)+'</button>':'')+'<button class="btn dark" data-modal-confirm'+(!cancelLabel?' autofocus':'')+'>'+esc(confirmLabel)+'</button></div>';
 document.body.appendChild(dialog);siteModal={dialog,focus};
 dialog.querySelector('[data-modal-cancel]')?.addEventListener('click',closeSiteModal);
 dialog.querySelector('[data-modal-confirm]').addEventListener('click',()=>{closeSiteModal();onConfirm?.();});
 dialog.addEventListener('cancel',event=>{event.preventDefault();closeSiteModal();});
 dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeSiteModal();}});
 dialog.showModal();
}

function answerOptionText(q,o){if(q.type==='진술 판정')return o.text;return (q.type==='매칭'?matchingLabel(q,o.id):itemLabel(o.id))+' · '+o.text;}
function answerChoicesHTML(q,a,index){return choicesFor(q).map((o,n)=>'<button class="picker-choice '+(a[index]===o.id?'selected':'')+'" data-option-id="'+esc(o.id)+'" data-choice="'+n+'" aria-pressed="'+(a[index]===o.id)+'" '+(q.type!=='진술 판정'&&a.includes(o.id)&&a[index]!==o.id?'disabled':'')+'>'+(a[index]===o.id?'✓ ':'')+esc(answerOptionText(q,o))+'</button>').join('');}
function showAnswerPicker(index){
 if(!active||paused||siteModal)return;
 const q=exams[selected].questions[current],a=answers[current],options=choicesFor(q),focus=document.activeElement,dialog=document.createElement('dialog');
 dialog.className='site-modal answer-dialog';dialog.setAttribute('aria-labelledby','picker-title');
 dialog.innerHTML='<div class="picker-header"><h2 id="picker-title">'+esc(q.type==='매칭'?tr('상황 ','Situation ')+itemLabel(q.items[index].id)+tr('의 답 선택',' — choose an answer'):tr('답안 선택','Choose an answer'))+'</h2><button class="smallbtn" data-close>'+tr('닫기','Close')+'</button></div>'+(q.type==='매칭'?'<div class="picker-situation">'+inline(q.items[index].text)+'</div>':'')+'<div class="picker-choices">'+answerChoicesHTML(q,a,index)+'</div><div class="modal-actions"><button class="btn secondary" data-clear>'+esc(tr('선택 해제','Clear selection'))+'</button></div>';
 document.body.appendChild(dialog);siteModal={dialog,focus};
 const select=value=>{closeSiteModal();assign(index,value);document.getElementById('answer-picker-'+index)?.focus({preventScroll:true});};
 dialog.querySelectorAll('[data-choice]').forEach(button=>button.addEventListener('click',()=>select(options[Number(button.dataset.choice)].id)));
 dialog.querySelector('[data-clear]').addEventListener('click',()=>select(''));
 dialog.querySelector('[data-close]').addEventListener('click',closeSiteModal);
 dialog.addEventListener('cancel',event=>{event.preventDefault();closeSiteModal();});
 dialog.showModal();dialog.querySelector('.picker-choice.selected:not(:disabled),.picker-choice:not(:disabled)')?.focus();
}

function matchingPromptText(text){return text.replaceAll('왼쪽의','각 상황의').replaceAll('왼쪽','각 상황의').replaceAll('오른쪽에서','보기에서').replaceAll('오른쪽','보기').replace(/on the left/gi,'in each situation').replace(/on the right/gi,'in the options').replace(/left-hand/gi,'situation').replace(/right-hand/gi,'available');}
function matchingOptionsList(q){return '<ul class="matching-option-list">'+choicesFor(q).map(o=>'<li><b>'+esc(matchingLabel(q,o.id))+'</b><span>'+inline(o.text)+'</span></li>').join('')+'</ul>';}
